#define MOD 1000000007LL

int main(void) {
    int H, W;
    if (scanf("%d %d", &H, &W) != 2) return 0;

    int *a = (int *)malloc((size_t)H * W * sizeof(int));
    if (!a) return 0;

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            scanf("%d", &a[i * W + j]);
        }
    }

    /*
      Assumed movement rules:
      - Start from any passable/jump cell in the top row.
      - Cell value 1 is blocked.
      - From a normal cell (0): move to next row, same column or adjacent columns.
      - From a jump pad (2): move to row + 2, same column or adjacent columns.
      Count ways to reach any cell in the bottom row.
    */

    long long *dp = (long long *)calloc((size_t)H * W, sizeof(long long));
    if (!dp) {
        free(a);
        return 0;
    }

    for (int j = 0; j < W; j++) {
        if (a[j] != 1) dp[j] = 1;
    }

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            long long cur = dp[i * W + j];
            if (cur == 0 || a[i * W + j] == 1) continue;

            int step = (a[i * W + j] == 2 ? 2 : 1);
            int ni = i + step;
            if (ni >= H) continue;

            for (int dj = -1; dj <= 1; dj++) {
                int nj = j + dj;
                if (nj < 0 || nj >= W) continue;
                if (a[ni * W + nj] == 1) continue;
                dp[ni * W + nj] = (dp[ni * W + nj] + cur) % MOD;
            }
        }
    }

    long long ans = 0;
    for (int j = 0; j < W; j++) {
        ans = (ans + dp[(H - 1) * W + j]) % MOD;
    }

    printf("%lld\n", ans);

    free(dp);
    free(a);
    return 0;
}

