public class SkiPatterns {
    static final int MOD = 1000000007;
    static int R, C;
    static int[][] grid;
    static long[][] dp;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        R = sc.nextInt();
        C = sc.nextInt();

        grid = new int[R][C];
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                grid[i][j] = sc.nextInt();
            }
        }

        dp = new long[R][C];
        for (long[] row : dp) {
            Arrays.fill(row, -1);
        }

        long total = 0;
        for (int j = 0; j < C; j++) {
            if (grid[0][j] == 0) {
                total = (total + solve(0, j)) % MOD;
            }
        }

        System.out.println(total);
    }

    static long solve(int r, int c) {
        if (r == R - 1) {
            return 1;
        }

        if (dp[r][c] != -1) {
            return dp[r][c];
        }

        long count = 0;

        if (grid[r][c] == 0) {
            // Normal cell - can go down-left, down, or down-right
            if (c > 0 && grid[r + 1][c - 1] != 1) {
                count = (count + solve(r + 1, c - 1)) % MOD;
            }
            if (grid[r + 1][c] != 1) {
                count = (count + solve(r + 1, c)) % MOD;
            }
            if (c < C - 1 && grid[r + 1][c + 1] != 1) {
                count = (count + solve(r + 1, c + 1)) % MOD;
            }
        } else if (grid[r][c] == 2) {
            // Jump pad - can jump 2 rows down
            if (r + 2 < R) {
                if (c > 0 && grid[r + 2][c - 1] != 1) {
                    count = (count + solve(r + 2, c - 1)) % MOD;
                }
                if (grid[r + 2][c] != 1) {
                    count = (count + solve(r + 2, c)) % MOD;
                }
                if (c < C - 1 && grid[r + 2][c + 1] != 1) {
                    count = (count + solve(r + 2, c + 1)) % MOD;
                }
            } else if (r + 1 < R) {
                // If can't jump 2 rows, try 1 row down
                if (c > 0 && grid[r + 1][c - 1] != 1) {
                    count = (count + solve(r + 1, c - 1)) % MOD;
                }
                if (grid[r + 1][c] != 1) {
                    count = (count + solve(r + 1, c)) % MOD;
                }
                if (c < C - 1 && grid[r + 1][c + 1] != 1) {
                    count = (count + solve(r + 1, c + 1)) % MOD;
                }
            }
        }

        dp[r][c] = count;
        return count;
    }
}

