    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();

        int[][] a = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                a[i][j] = fs.nextInt();
            }
        }

        // dp[i][j] = number of ways to arrive at cell (i, j)
        long[][] dp = new long[n][m];

        // Skiers start from any passable/jump cell in the top row
        for (int j = 0; j < m; j++) {
            if (a[0][j] != 1) dp[0][j] = 1;
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (a[i][j] == 1 || dp[i][j] == 0) continue;

                if (a[i][j] == 0) {
                    // Normal cell: can move to next row, same column or adjacent columns
                    int ni = i + 1;
                    if (ni < n) {
                        for (int dj = -1; dj <= 1; dj++) {
                            int nj = j + dj;
                            if (0 <= nj && nj < m && a[ni][nj] != 1) {
                                dp[ni][nj] += dp[i][j];
                                if (dp[ni][nj] >= MOD) dp[ni][nj] %= MOD;
                            }
                        }
                    }
                } else if (a[i][j] == 2) {
                    // Jump pad: jump over one row, landing in row i+2
                    int ni = i + 2;
                    if (ni < n) {
                        for (int dj = -2; dj <= 2; dj++) {
                            int nj = j + dj;
                            if (0 <= nj && nj < m && a[ni][nj] != 1) {
                                dp[ni][nj] += dp[i][j];
                                if (dp[ni][nj] >= MOD) dp[ni][nj] %= MOD;
                            }
                        }
                    }
                }
            }
        }

        long ans = 0;
        for (int j = 0; j < m; j++) {
            ans += dp[n - 1][j];
            if (ans >= MOD) ans %= MOD;
        }

        System.out.println(ans % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

