from functools import lru_cache

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    R = int(input_data[idx]); idx += 1
    C = int(input_data[idx]); idx += 1

    grid = []
    for r in range(R):
        row = []
        for c in range(C):
            row.append(int(input_data[idx])); idx += 1
        grid.append(row)

    # dp[r][c] = number of paths starting from cell (r,c) that reach the bottom
    # Use memoization

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(r, c):
        if r >= R:
            return 1  # successfully reached bottom
        if grid[r][c] == 1:
            return 0  # obstacle

        total = 0
        cell_type = grid[r][c]

        if cell_type == 0 or cell_type == 2:
            step = 2 if cell_type == 2 else 1
            for dc in [-1, 0, 1]:
                nr, nc = r + step, c + dc
                if nc < 0 or nc >= C:
                    continue
                if nr >= R:
                    total += 1  # reached beyond bottom
                elif grid[nr][nc] != 1:
                    total += dp(nr, nc)

        return total

    # Count paths starting from any non-obstacle cell in row 0
    answer = 0
    for c in range(C):
        if grid[0][c] != 1:
            answer += dp(0, c)

    print(answer)

